events=[]
def words(text,protected):
    if protected:
        try:return text.lower().split()
        finally:events.append('done')
    return text.upper().split()
def outer():
    seen=[]
    for item in [(' A B ',False),(' C D ',True),(' E F ',False)]:
        for word in words(item[0],item[1]):
            seen.append(word)
            if word=='c':break
        for character in 'XY':seen.append(character)
        for number in (1,2):seen.append(number)
    print(seen,events)
outer()

def outer():
 count=0
 def words(value=' A B '):
  nonlocal count
  count+=1
  return value.lower().split()
 def forward(value):return words(value=value)
 for word in forward(' C D '):print(word)
 result=forward(' E F ')
 result.append('g')
 print(type(result).__name__,result)
 words.__defaults__=(' NEW WORD ',)
 print([word for word in words()])
 print(count)
outer()

events=[]
class Manager:
 def __enter__(self):events.append('enter')
 def __exit__(self,*args):events.append('exit');return False
def outer():
 count=0
 def words(value,override=False):
  nonlocal count
  count+=1
  with Manager():
   try:return value.upper().split()
   finally:
    events.append('finally')
    if override:return ['override']
 for word in words(' a b '):events.append(word)
 for word in words(' ignored ',True):events.append(word)
 result=words(' c d ')
 print(events,type(result).__name__,result,count)
outer()

def outer():
 count=0
 def words(value):
  nonlocal count
  count+=1
  return value.lower().split()
 def generate():
  yield 'start'
  return words(' A B ')
 generator=generate()
 print(next(generator))
 try:next(generator)
 except StopIteration as done:print(type(done.value).__name__,done.value)
 def delegated():yield from words(' C D ')
 print(list(delegated()),count)
outer()

def outer():
 count=0
 def words(value):
  nonlocal count
  count+=1
  try:raise ValueError('local')
  except ValueError as error:
   return value.lower().split()
 try:raise RuntimeError('outer')
 except RuntimeError as previous:
  for word in words(' A B '):
   try:raise LookupError(word)
   except LookupError as error:print(word,error.__context__ is previous)
 print(count)
outer()

kept=[]
def outer():
 count=0
 def words(value,store):
  nonlocal count
  count+=1
  if store:
   result=value.upper().rsplit()
   kept.append(result)
   return result
  return value.lower().split()
 print([word for word in words(' A B ',False)])
 for word in words(' c d ',True):
  print(word,type(kept[-1]).__name__)
 print(words(' E F ',False),count)
outer()
